import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.B2-MWMH0.js";var i=JSON.parse(`{"title":"Core and runtime updates","description":"","frontmatter":{},"headers":[],"relativePath":"docs/operations/upgrades-and-rollback.md","filePath":"docs/operations/upgrades-and-rollback.md"}`),a={name:`docs/operations/upgrades-and-rollback.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="core-and-runtime-updates" tabindex="-1">Core and runtime updates <a class="header-anchor" href="#core-and-runtime-updates" aria-label="Permalink to “Core and runtime updates”">​</a></h1><p><a href="./../">Back to documentation</a></p><p>Check core and runtime availability without changing either one:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">letsinfer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>Core availability comes from the signed GitHub release channel. Runtime availability comes from the signed catalog and immutable OCI digest for your selected candidate. The node agent refreshes this state periodically, and interactive commands read the local snapshot without delaying administration on a network request.</p><p>The private update database is <code>$LETSINFER_HOME/state/updates.sqlite3</code>. It stores component identities, versions, immutable sources, results, and verification times—never credentials. Every catalog consumer shares the last verified immutable snapshot below <code>$LETSINFER_HOME/state/catalog/</code>; a damaged cache is replaced by a fresh signature-verified download and a temporary network failure may use the last verified snapshot without changing a running runtime.</p><h2 id="update-core" tabindex="-1">Update core <a class="header-anchor" href="#update-core" aria-label="Permalink to “Update core”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">letsinfer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Core update installs the new immutable version beside the active one, rebinds your existing services and unchanged runtime, and verifies the launcher and service handoff. Only then does it remove superseded validated core versions, unreferenced control bundles, and old Watchdog builds.</p><p>If the handoff fails, the previous core remains available. Core cleanup never removes runtime rollback objects, models, benchmark evidence, or runtime selection history.</p><h2 id="upgrade-a-runtime" tabindex="-1">Upgrade a runtime <a class="header-anchor" href="#upgrade-a-runtime" aria-label="Permalink to “Upgrade a runtime”">​</a></h2><p>Your installation records one policy:</p><ul><li><code>recommended</code> follows the current catalog recommendation;</li><li><code>runtime:CANDIDATE_ID</code> stays on that exact candidate line;</li><li><code>pinned</code> and <code>local</code> move only when you provide <code>--to</code>.</li></ul><p>Preview and apply:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">letsinfer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3.8-27b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">letsinfer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3.8-27b</span></span></code></pre></div><p>Choose an exact immutable source:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">letsinfer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3.8-27b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/example/runtime@sha256:</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">diges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Let&#39;s Infer verifies and stages the candidate before replacing the active service. Model, Engine OCI, runtime pack, target, memory, Watchdog, health, authentication, and served identity must all pass. A failed activation restores the previous configuration and running service.</p><h2 id="roll-back" tabindex="-1">Roll back <a class="header-anchor" href="#roll-back" aria-label="Permalink to “Roll back”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">letsinfer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3.8-27b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">letsinfer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen3.8-27b</span></span></code></pre></div><p>Rollback uses the retained immutable object and receipt. It never resolves a mutable tag or reinterprets the old catalog entry.</p><p>Core update, runtime upgrade, and rollback are explicit independent actions. None silently changes the other component.</p>`,22)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};